\label{prop:actuallyQuasiMetricSpace}
The matrix-valued expression (\ref{eq:definitionOfDistance}) satisfies properties similar to the (real-valued) quasi-metrics, \textit{i.e. } it satisfies:
\begin{enumerate}
    \item $D_{ij}(u_1,u_2)\geq 0$;
    \item $D_{ij}(u_1,u_2)=0 \iff u_1=u_2$ and $i=j$;
    \item $\latMatr{D}(u_1,u_2) = \latMatr{D}(u_1,u_2)^\top = \latMatr{D}(u_2,u_1) = \latMatr{D}(u_2,u_1)^\top$ for any $u_1, u_2 \in \mathcal G$;
    \item The mapping $(u_1,u_2) \mapsto \latMatr{D}(u_1,u_0) \latMatr{A} + \latMatr{A}^\top \latMatr{D}(u_0,u_2) - \latMatr{D}(u_1,u_2) - \latMatr{A}^\top \latMatr{D}(u_0,u_0) \latMatr{A}$ is positive semidefinite for any $u_0 \in \mathcal G$ and any $p\times p$ matrix $\latMatr{A}$ such that $\latMatr{A}^\top {\mathbf{1}_{p}} = {\mathbf{1}_{p}}$;
    \item {The matrices $\latMatr{D}(u_1,u_2)-\latMatr{D}(u_0,u_0)$ and  $2\latMatr{D}(u_1,u_0)+2\latMatr{D}(u_2,u_0)-\latMatr{D}(u_1,u_2)-3\latMatr{D}(u_0,u_0)$ are symmetric and positive semidefinite for any $u_0,u_1,u_2 \in \mathcal G$.}
\end{enumerate}

\label{prop:ourDistProperties}
Let ${\cal G}$ be a graph with Euclidean edges and let $\latMatr{D}: \mathcal G\times \mathcal G \to {[0,+\infty)}^{p\times p}$ as defined in (\ref{eq:definitionOfDistance}) and having elements $D_{ij}$, $i,j=1,\ldots, p$. Then, the following properties hold: 
\begin{enumerate}
    \item for all $i\in\curly{1,\dots,p}$, the distance $D_{ii}$ coincides with the resistance distance defined by \cite{anderes_isotropic_2020}, \textit{i.e. } $D_{ii}(u_1,u_2)=d_{R}(u_1,u_2)$;
    \item the distance $\latMatr{D}$ is matrix-homogeneous, \textit{i.e. } for every $ i\ne j$ and $\,i'\ne j'$, we have $D_{ij}(u_1,u_2)=D_{i'j'}(u_1,u_2)$ and $D_{ii}(u_1,u_2)=D_{i'i'}(u_1,u_2)$.  
\end{enumerate}

