         \dVec k&:={\latMatr{L}}^-\dVec x & \dVec h&:=\dVec x^\top {\latMatr{L}}^-\\
         \dVec u&:=\round{\latMatr{I}_n-\latMatr L{\latMatr{L}}^-}\dVec x=\frac{1}{n} {\mathbf{1}_{n\times n}} \dVec x & \dVec v&:= \dVec x^\top \round{\latMatr{I}_n-{\latMatr{L}}^- \latMatr L} = \frac{1}{n} \dVec x^\top {\mathbf{1}_{n\times n}}\\
         \beta &:= 1+\dVec x^\top \latMatr L^- \dVec x.
     \end{align*}
     In addition, we have $\norm{\dVec u}^2=\norm{\dVec v}^2= \dVec u^\top \dVec u = \frac{1}{n^2}{\mathbf{1}_{n}}^\top ({\mathbf{1}_{n}}^\top \dVec x)({\mathbf{1}_{n}}^\top \dVec x) {\mathbf{1}_{n}} = \frac{1}{n}({\mathbf{1}_{n}}^\top \dVec x)^2\ne 0$. Let us finally apply Equation (3.1) of \cite{meyer_generalized_1973}:
     \begin{align*}
         \round{{\latMatr{L}}+\dVec x \dVec x^\top}^-&={\latMatr{L}}^- - \dVec k \dVec u^- - \dVec v^- \dVec h +\beta \dVec v^- \dVec u^-\\
         &={\latMatr{L}}^--\frac{\dVec k\dVec u^\top}{\norm{\dVec u}^2} - \frac{\dVec v^\top \dVec h}{\norm{\dVec v}^2} + \beta \frac{\dVec v^\top \dVec u^\top}{\norm{\dVec v}^2 \norm{\dVec u}^2}\\
         &={\latMatr{L}}^- - \frac{{\latMatr{L}}^- \dVec x {\mathbf{1}_{n}}^\top}{{\mathbf{1}_{n}}^\top \dVec x} - \frac{{\mathbf{1}_{n}} \dVec x^\top {\latMatr{L}}^-}{{\mathbf{1}_{n}}^\top \dVec x} + \round{1+ \dVec x^\top {\latMatr{L}}^- \dVec x} \frac{{\mathbf{1}_{n\times n}}}{\round{{\mathbf{1}_{n}}^\top \dVec x}^2}.
     \end{align*}
     To show (\ref{eq:thesisRank1Update}), it is now sufficient to prove that
     \begin{equation*}
         \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}^\top \round{\round{1+ \dVec x^\top {\latMatr{L}}^- \dVec x} \frac{{\mathbf{1}_{n\times n}}}{\round{{\mathbf{1}_{n}}^\top \dVec x}^2}- \frac{{\latMatr{L}}^- \dVec x {\mathbf{1}_{n}}^\top}{{\mathbf{1}_{n}}^\top \dVec x} - \frac{{\mathbf{1}_{n}} \dVec x^\top {\latMatr{L}}^-}{{\mathbf{1}_{n}}^\top \dVec x}}\round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}=0.
     \end{equation*}
     It is possible to see this by noticing that ${\mathbf{1}_{n}}^\top \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}={\mathbf{1}_{n}}^\top \dVec{\delta}_{1,V} - {\mathbf{1}_{n}}^\top \dVec{\delta}_{2,V}= 1-1=0$ and similarly $\round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}^\top {\mathbf{1}_{n}}=0$, therefore each term of the above equation equals 0.\par
     As a consequence,
     \begin{align*}
         d_{R}^V(u_1,u_2)&=\round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}^\top {\grMatr{\Sigma}}_{\latMatr{A}} \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}} \\
         &= \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}^\top \round{{\latMatr{L}}+\dVec e_j \dVec e_j^\top}^- \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}} \\
         &= \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}}^\top {\latMatr{L}}^- \round{\dVec{\delta}_{1,V}-\dVec{\delta}_{2,V}} = {D}_{ii}^V(u_1,u_2).
     \end{align*}

    \item The proof of this point is straightforward from Equation (\ref{eq:explicitWritingMultivMetric}): notice that ${D}_{ij}(u_1,u_2)$, for $i\ne j$, is the off-diagonal element of ${\latMatr{D}}(u_1,u_2)$, whilst ${D}_{ii}(u_1,u_2)$ is the main diagonal one.
\end{enumerate}

