    & \qquad + \frac{1}{6} \round{\alpha (p-2)\cdot \frac{1}{3}+\sqrt{1-2\alpha(p-2)\cdot \frac{1}{3} +\alpha^2 p^2 \cdot \frac{1}{3^2}}-1} \\
